import functools

def _parse(v):
    # strip build metadata
    main = v.split('+', 1)[0]
    if '-' in main:
        core, pre = main.split('-', 1)
    else:
        core, pre = main, None
    core_parts = tuple(int(x) for x in core.split('.'))
    pre_parts = pre.split('.') if pre is not None else None
    return core_parts, pre_parts

def _compare_identifiers(a, b):
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        ai, bi = int(a), int(b)
        if ai < bi:
            return -1
        elif ai > bi:
            return 1
        else:
            return 0
    elif a_num and not b_num:
        return -1
    elif not a_num and b_num:
        return 1
    else:
        if a < b:
            return -1
        elif a > b:
            return 1
        else:
            return 0

def _compare(v1, v2):
    core1, pre1 = _parse(v1)
    core2, pre2 = _parse(v2)

    if core1 < core2:
        return -1
    elif core1 > core2:
        return 1

    if pre1 is None and pre2 is None:
        return 0
    elif pre1 is None and pre2 is not None:
        return 1
    elif pre1 is not None and pre2 is None:
        return -1
    else:
        for a, b in zip(pre1, pre2):
            c = _compare_identifiers(a, b)
            if c != 0:
                return c
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        else:
            return 0

def semver_sort(versions):
    indexed = list(enumerate(versions))

    def cmp(item1, item2):
        i1, v1 = item1
        i2, v2 = item2
        c = _compare(v1, v2)
        if c != 0:
            return c
        return i1 - i2

    indexed.sort(key=functools.cmp_to_key(cmp))
    return [v for i, v in indexed]

